import { unlink } from 'node:fs/promises'

/** Own only paths generated by this plugin instance, never caller-supplied paths. */
export class CaptureRetention {
  private readonly owned = new Set<string>()
  private readonly previews: string[] = []
  private closed = false

  constructor(
    private readonly maxPreviews = 24,
    private readonly remove: (path: string) => Promise<void> = unlink,
  ) {
    if (!Number.isSafeInteger(maxPreviews) || maxPreviews < 1) throw new RangeError('Invalid preview limit')
  }

  async record(path: string, preview: boolean): Promise<void> {
    if (!path) throw new TypeError('Capture path is empty')
    this.owned.add(path)
    if (this.closed) { await this.removeOwned(path); return }
    if (!preview) return
    this.previews.push(path)
    while (this.previews.length > this.maxPreviews) {
      await this.removeOwned(this.previews.shift()!)
    }
  }

  async dispose(): Promise<void> {
    this.closed = true
    await Promise.all([...this.owned].map(path => this.removeOwned(path)))
    this.previews.length = 0
  }

  private async removeOwned(path: string): Promise<void> {
    try {
      await this.remove(path)
      this.owned.delete(path)
    } catch { /* A file still in use can be retried on disposal. */ }
  }
}
